[1879109787] = {["ID"] = 1879109787; ["i"] = 6; ["j"] = 11; ["k"] = 4; ["TYPE"] = 3; ["VXP"] = 2000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Древние камни Форохеля"; ["LORE"] = "Хотя среди самих лоссотов Форохеля не встречалось великих строителей, в давние времена на севере располагались рудники и поселения гномов."; ["SUMMARY"] = "Find 5 ancient structures in Forochel"; };
[1879109788] = {["ID"] = 1879109788; ["i"] = 6; ["j"] = 11; ["k"] = 7; ["TYPE"] = 7; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 300; ["FACTION"] = 1879103954; ["TIER"] = 3; ["NAME"] = "Экспедиция в Форохель"; ["LORE"] = "Лоссоты Форохеля постоянно воюют с гаураданами, дикой северной природой и самими стихиями. Казалось бы, они с благодарностью должны принимать любую помощь - но напротив, трудности лишь закалили их независимый характер. Будет не так-то просто завоевать их доверие и уговорить принять сторону свободных народов Эриадора в грядущей войне."; ["SUMMARY"] = "Complete 10 quests in Forochel"; };
[1879109789] = {["ID"] = 1879109789; ["i"] = 6; ["j"] = 11; ["k"] = 6; ["TYPE"] = 7; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 2; ["NAME"] = "Выживший в Форохеле"; ["LORE"] = "Главная опасность Форохеля - суровая природа. Жестокие ветры и льды забрали больше жизней, чем когти калпа-кита или копья гаураданов, хотя и эти две угрозы приносят лоссотам немало бед."; ["SUMMARY"] = "Complete 20 quests in Forochel"; };
[1879109790] = {["ID"] = 1879109790; ["i"] = 6; ["j"] = 11; ["k"] = 5; ["TYPE"] = 7; ["VXP"] = 2000; ["LP"] = 15; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 1; ["NAME"] = "Первопроходец Форохеля"; ["LORE"] = "Жестокая природа Форохеля не щадит никого, кроме самых стойких. Но те, у кого хватает духа выжить в этих местах, навеки проникаются любовью и уважением к этой земле."; ["SUMMARY"] = "Complete 30 quests in Forochel"; };
[1879109791] = {["ID"] = 1879109791; ["i"] = 6; ["j"] = 11; ["k"] = 10; ["TYPE"] = 4; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Убийца ангмарцев"; ["LORE"] = "Похоже, что рука Ангмара дотянулась даже до отдаленного Форохеля, посеяв там семена раздора. Впрочем, здесь их злые козни не так сильны, как в прочих местах - возможно, они не придают Форохелю большого значения. Здесь почти нет привычных орков и людей, принявших сторону Тьмы. Ангмар предпочел опираться на помощь Крепкохватов и дикарей-гаураданов."; ["SUMMARY"] = "Defeat 100 Angmarim in Forochel"; ["TITLE"] = "Гроза Ангмара"; };
[1879109792] = {["ID"] = 1879109792; ["i"] = 6; ["j"] = 11; ["k"] = 9; ["TYPE"] = 4; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Убийца ангмарцев (продолжение)"; ["LORE"] = "Похоже, что ангмарцы либо что-то ищут в Форохеле, либо просто ищут свою выгоду в распрях между лоссотами и гаураданами. Они не хотят захватывать эти земли - по крайней мере, сейчас."; ["SUMMARY"] = "Defeat 200 Angmarim in Forochel"; };
[1879109793] = {["ID"] = 1879109793; ["i"] = 6; ["j"] = 11; ["k"] = 12; ["TYPE"] = 4; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Убийца Крепкохватов"; ["LORE"] = "Древние гномьи развалины встречаются повсюду в Форохеле. Самые выносливые из всех свободных народов, гномы утверждают, что пришли сюда в стародавние времена, надеясь отыскать в мерзлой земле несметные богатства. Все их поселения ныне заброшены. Желая доказать свое происхождение от древних гномьих владык, Крепкохваты задумали отстроить эти развалины с помощью своих ангмарских союзников. Разумеется, на север сразу же пришли Длиннобороды, дабы оспорить эти притязания - вне зависимости от того, насколько хороши местные рудники."; ["SUMMARY"] = "Defeat 100 Dourhand Dwarves in Forochel"; ["TITLE"] = "Смотритель Рудника"; };
[1879109794] = {["ID"] = 1879109794; ["i"] = 6; ["j"] = 11; ["k"] = 11; ["TYPE"] = 4; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Убийца Крепкохватов (продолжение)"; ["LORE"] = "Попытки Крепкохватов провозгласить себя наследниками древних гномьих владык оказались тщетными: всему Средиземью известно об их предательском союзе с Ангмаром. Но от этого они сражаются лишь отчаяннее, ведь теперь им приходится отстаивать собственное право на жизнь."; ["SUMMARY"] = "Defeat 200 Dourhand Dwarves in Forochel"; };
[1879109795] = {["ID"] = 1879109795; ["i"] = 6; ["j"] = 11; ["k"] = 14; ["TYPE"] = 4; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Убийца гаураданов"; ["LORE"] = "Теперь, обнаружив родину гаураданов, вы стали понимать, откуда проистекает их жестокая мощь. Яростные стихии и дикая природа Форохеля мяли и ломали людей Волка, пока не вылепили из них суровых дикарей... И не мудрено. С другой стороны, лоссоты, живущие в тех же краях, смогли остаться людьми. Сами ли гаураданы выбрали свой путь - или же их сердца давным-давно смутил коварный Враг?"; ["SUMMARY"] = "Defeat 100 Gauradan in Forochel"; ["TITLE"] = "Гроза Дикарей"; };
[1879109796] = {["ID"] = 1879109796; ["i"] = 6; ["j"] = 11; ["k"] = 13; ["TYPE"] = 4; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Убийца гаураданов (продолжение)"; ["LORE"] = "Удивительно, что два таких разных народа, как гаураданы и лоссоты, ведут бесконечные сражения за ледяные суровые пустоши. Похоже, дело в том, что здесь их родина. А родину, как известно, не выбирают, и свою землю готов защищать каждый - будь то человек, гном, хоббит, эльф или орк."; ["SUMMARY"] = "Defeat 200 Gauradan in Forochel"; };
[1879109797] = {["ID"] = 1879109797; ["i"] = 6; ["j"] = 11; ["k"] = 16; ["TYPE"] = 4; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Убийца мраков"; ["LORE"] = "Гаураданы верят, что мраки - это неупокоенные души людей Волка, изгнанных из племени за трусость и обреченных на гибель во льдах. Души эти ждет вечное скитание по холодным снежным равнинам. Мудрецы же, тем временем, полагают, что эти существа - падшие духи, оставшихся здесь со времен падения Темного Властелина."; ["SUMMARY"] = "Defeat 40 Grims in Forochel"; ["TITLE"] = "Бич Льда"; };
[1879109798] = {["ID"] = 1879109798; ["i"] = 6; ["j"] = 11; ["k"] = 15; ["TYPE"] = 4; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Убийца мраков (продолжение)"; ["LORE"] = "Даже если мраки и сохранили частичку своей некогда живой души, они лишены милосердия, и пощады от них ждать не приходится. Они нападают, едва почуяв тепло или жизнь, одержимые желанием уничтожить объект своей ненависти."; ["SUMMARY"] = "Defeat 80 Grims in Forochel"; };
[1879109799] = {["ID"] = 1879109799; ["i"] = 6; ["j"] = 11; ["k"] = 18; ["TYPE"] = 4; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Убийца саблезубов"; ["LORE"] = "Эти дикие кошки - злобные и коварные хищники. Лоссоты стараются не заходить в их владения даже во время охоты, чтобы не стать добычей этих смертоносных зверей. Сами же саблезубы без страха подходят к деревням лоссотов и режут скот."; ["SUMMARY"] = "Defeat 100 Sabre-tooths in Forochel"; ["TITLE"] = "Гроза Когтей"; };
