[1879201468] = {["ID"] = 1879201468; ["i"] = 2; ["j"] = 5; ["k"] = 16; ["TYPE"] = 4; ["LP"] = 15; ["TIER"] = 2; ["MIN_LVL"] = 65; ["NAME"] = "Больные и мертвые"; ["LORE"] = "Наемники, которым хватило глупости последовать за Ферндуром в недра Затерянного храма, заразились чумой и погибли. Их тела, одержимые падшими духами, бродят по катакомбам. Они дожидаются приказа Ферндура, чтобы подняться наверх и погубить Средиземье. Уничтожьте как можно больше этих мертвецов."; ["SUMMARY"] = "Defeat 150 wights in the crypts of the Lost Temple"; ["TITLE"] = "длань очищения"; };
