[1879227678] = {["ID"] = 1879227678; ["i"] = 2; ["j"] = 6; ["k"] = 27; ["TYPE"] = 6; ["LP"] = 5; ["TIER"] = 3; ["MIN_LVL"] = 75; ["NAME"] = "Башня Ортханк: Кольцо яда - ур. I"; ["LORE"] = "Зло Сарумана перешло все мыслимые и немыслимые границы. Он решил создать себе новых слуг - еще чернее и ужаснее прежних. Он запер орков, дунландцев и варгов в зале, заполненном кислотой и ядовитыми газами, а затем применил малое кольцо власти... Чудовищ, которые у него получились, трудно вообразить."; ["SUMMARY"] = "Claim the Ring of Acid"; };
[1879227679] = {["ID"] = 1879227679; ["i"] = 2; ["j"] = 6; ["k"] = 33; ["TYPE"] = 6; ["LP"] = 5; ["TIER"] = 3; ["MIN_LVL"] = 75; ["NAME"] = "Башня Ортханк: Кольцо яда - ур. II"; ["LORE"] = "Зло Сарумана перешло все мыслимые и немыслимые границы. Он решил создать себе новых слуг - еще чернее и ужаснее прежних. Он запер орков, дунландцев и варгов в зале, заполненном кислотой и ядовитыми газами, а затем применил малое кольцо власти... Чудовищ, которые у него получились, трудно вообразить. Это деяние необходимо выполнять на II уровне сложности рейда 'Башня Ортханк'."; ["SUMMARY"] = "Claim the Ring of Acid"; };
[1879227680] = {["ID"] = 1879227680; ["i"] = 2; ["j"] = 6; ["k"] = 28; ["TYPE"] = 6; ["LP"] = 5; ["TIER"] = 3; ["MIN_LVL"] = 75; ["NAME"] = "Башня Ортханк: Шаровая молния - ур. I"; ["LORE"] = "Свободные народы считают троллей отвратительными безмозглыми существами - и в целом это совершеннейшая правда. Но некоторые тролли, напротив, оказываются умнейшими созданиями и опаснейшими из слуг Темного властелина. Именно таков враг, с которым вам предстоит сразиться. Его сила многократно возросла с тех пор, как Саруман вручил ему кольцо, наделенное силой бурь..."; ["SUMMARY"] = "Claim the Ring of Lightning"; };
[1879227681] = {["ID"] = 1879227681; ["i"] = 2; ["j"] = 6; ["k"] = 34; ["TYPE"] = 6; ["LP"] = 5; ["TIER"] = 3; ["MIN_LVL"] = 75; ["NAME"] = "Башня Ортханк: Шаровая молния - ур. II"; ["LORE"] = "Свободные народы считают троллей отвратительными безмозглыми существами - и в целом это совершеннейшая правда. Но некоторые тролли, напротив, оказываются умнейшими созданиями и опаснейшими из слуг Темного властелина. Именно таков враг, с которым вам предстоит сразиться. Его сила многократно возросла с тех пор, как Саруман вручил ему кольцо, наделенное силой бурь... Это деяние необходимо выполнять на II уровне сложности рейда 'Башня Ортханк' (чертоги молний)."; ["SUMMARY"] = "Claim the Ring of Lightning"; };
[1879227682] = {["ID"] = 1879227682; ["i"] = 2; ["j"] = 6; ["k"] = 36; ["TYPE"] = 6; ["LP"] = 5; ["TIER"] = 3; ["MIN_LVL"] = 75; ["NAME"] = "Башня Ортханк: Кольцо теней - ур. II"; ["LORE"] = "В тронном зале Ортханка вас ждет сражение с учеником Сарумана, могучим орком-осквернителем, владеющим кольцом теней. Этого противника так просто не одолеть. Это деяние необходимо выполнять на II уровне сложности рейда 'Башня Ортханк'."; ["SUMMARY"] = "Claim the Ring of Shadow"; };
