[1879316232] = {["ID"] = 1879316232; ["i"] = 5; ["j"] = 1; ["k"] = 360; ["TYPE"] = 8; ["CRV"] = "Class"; ["SUBTYPE"] = 214; ["LP"] = 10; ["MIN_LVL"] = 39; ["NAME"] = "Странствие хоббита"; ["LORE"] = "Первые четыре страницы этой книги можно найти, сражаясь в Ангмаре, Эрегионе и Мории, а следующие четыре - в Форохеле, Мории и Мглистых горах. Эта рукопись была написана Бильбо Торбинсом, хоббитом из Шира, который отправился в неожиданное и удивительное приключение. Вы перелистываете страницы с интересом, чтобы прочитать отрывок о его встрече с вашим предком Беорном, но никак не можете найти нужное место. Многие страницы из середины книги пропали. Кажется, что целая глава отсутствует. Не та ли это глава, в которой он встретил Беорна?"; ["SUMMARY"] = "Buy A Hobbit's Holiday from a Beorning Trainer and find the missing pages (8)"; };
[1879316233] = {["ID"] = 1879316233; ["i"] = 5; ["j"] = 1; ["k"] = 362; ["TYPE"] = 8; ["CRV"] = "Class"; ["SUBTYPE"] = 214; ["LP"] = 10; ["MIN_LVL"] = 39; ["NAME"] = "Родословная беорнингов"; ["LORE"] = "Первые четыре страницы этой книги можно найти, сражаясь в Ангмаре, Эрегионе и Мории, а следующие четыре - в Форохеле, Мории и Мглистых горах. В книге рассказывается о фамильных древах, различных линиях и ветвях вашего рода, правда некоторых страниц недостает. Вы не знаете, кто написал эту книгу, но, может быть, Бильбо Торбинсу, ныне живущему в Ривенделле, что-нибудь известно о ней. Его интересуют подобные вещи и он знал вашего родственника Беорна."; ["SUMMARY"] = "Buy Genealogy of the Beornings from a Beorning Trainer and find the missing pages (8)"; };
[1879316234] = {["ID"] = 1879316234; ["i"] = 5; ["j"] = 1; ["k"] = 361; ["TYPE"] = 8; ["CRV"] = "Class"; ["SUBTYPE"] = 214; ["LP"] = 10; ["MIN_LVL"] = 39; ["NAME"] = "Изучение сменяющих обличье"; ["LORE"] = "Первые четыре страницы этой книги можно найти в Ангмаре, Эрегионе и Мории. Оставшиеся четыре следует искать в Форохеле, Мории и Мглистых горах. Это любопытное руководство описывает саму суть вашего рода, и способность принимать обличье зверя. Описание составлено много лет назад и его автор, судя по всему, имел весьма поверхностные знания о предмете своего изучения. Вы задаетесь вопросом, есть ли хоть сколько-то правды в этом рассказе, полном преувеличений и недостоверных сведений. Нескольких страниц не хватает, а в саму книгу вложен пергамент с надписью 'Расспросить Бильбо.'"; ["SUMMARY"] = "Buy A Study of the Skin-changer from a Beorning Trainer and find the missing pages (8)"; };
