[1879358734] = {["ID"] = 1879358734; ["i"] = 2; ["j"] = 10; ["k"] = 23; ["TYPE"] = 4; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 115; ["NAME"] = "Бездна Мордат - уровень I"; ["LORE"] = "Одержимый желанием вновь завладеть утерянным кольцом Мантриф, король Васкмун Серозуб привел своих подданных гномов Огнерогов к Бездне Мордат, что находится в самой глубине подземелий Барад-Дура. Вместе с тем, сторонники тайного Ордена Ока, стремятся отомстить королю гномов за предательство и не допустить, чтобы он завладел наследием Тёмного Властелина. И не одна из противоборствующих сторон не знает, какой ужас сокрыт в глубинах Бездны Мордат."; ["SUMMARY"] = "Complete 3 deeds"; ["TITLE"] = "свет Черных Ям"; };
