[1879358759] = {["ID"] = 1879358759; ["i"] = 2; ["j"] = 10; ["k"] = 31; ["TYPE"] = 4; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 115; ["NAME"] = "Бездна Мордат: Владыка семи Колец Власти - уровень II"; ["LORE"] = "Король Васкмун Серозуб спустился в Мордат, чтобы разыскать утерянное гномье кольцо Власти, Мантриф, и ничто в этом мире не способно удержать его от этой затеи. Тем не менее, судьба семи гномьих колец Власти сокрыта в глубинах мрака, и вполне возможно в скором времени страшная правда вырвется наружу."; ["SUMMARY"] = "Prevent King Vaskmun Greytooth from recovering Mantríf on Tier 2"; };
[1879358760] = {["ID"] = 1879358760; ["i"] = 2; ["j"] = 10; ["k"] = 35; ["TYPE"] = 4; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 115; ["NAME"] = "Бездна Мордат: Сила гномьих колец"; ["LORE"] = "Одержимый жаждой вновь овладеть гномьим кольцом Мантриф, король Васкмун Серозуб привёл своих подданных гномов Огнерогов в Бездну Мордат, интересно в каком закоулке подземелий скрывается пропавшее гномье кольцо? Это деяние необходимо выполнять на уровне сложности II рейда 'Бездна Мордат'."; ["SUMMARY"] = "Defeat Fingar the Greedy after fully overcoming every manifestation of Dragon-spell on Tier 2"; };
