[1879468428] = {["ID"] = 1879468428; ["i"] = 8; ["j"] = 10; ["k"] = 1; ["TYPE"] = 7; ["VXP"] = 4000; ["MIN_LVL"] = 133; ["NAME"] = "Деяния Внешнего Гондора"; ["LORE"] = "После окончания Войны Кольца народы Анфаласа и Пиннат-Гелина оплакивают потерю своих владык и борются с корсарами Умбара и прочими врагами, пытаясь восстановить давно отсутствовавший мир во Внешнем Гондоре."; ["TITLE"] = "Обновитель Внешнего Гондора"; };
[1879468651] = {["ID"] = 1879468651; ["i"] = 5; ["j"] = 2; ["k"] = 55; ["TYPE"] = 4; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 5; ["MIN_LVL"] = 13; ["NAME"] = "Истребление волков"; ["LORE"] = "Волки издавна досаждали мирным речным хоббитам Туманного убежища. В суровые зимы они частенько забредают к истокам Долгой реки и в долину Андуина на юге, охотясь в злобных стаях на домашний скот и угрожая самим речным хоббитам. В наши дни, однако, приходится удивляться, ибо они приходят с Севера всё большими и большими стаями, и, похоже, они не просто голодны - ходят слухи, что многие из этих стай были выведены каким-то новым злом, чтобы быть особенно злобными и охотиться на неосторожных и слабых, а также вынюхивать тех, кто хочет скрыться от глаз врага."; };
[1879468653] = {["ID"] = 1879468653; ["i"] = 5; ["j"] = 2; ["k"] = 54; ["TYPE"] = 4; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 10; ["MIN_LVL"] = 19; ["NAME"] = "Истребление волков II"; ["LORE"] = "В старых сказаниях говорится о гоблинах, летучих мышах и варгах, преданных древнему повелителю орков, правившему горой Гундабад. Говорят, что его злодеяния были столь велики, что привлекли в окрестные земли всевозможных нечистых тварей, не последнюю роль среди которых играют злобные волки, издавна беспокоившие речных хоббитов Туманного убежища. Неужели подобное случилось вновь? Неужели на Севере зашевелилось новое зло? Какой бы ни была правда, то, что теперь волки встречаются почти по всему Средиземью, кажется дурным предзнаменованием."; };
[1879468656] = {["ID"] = 1879468656; ["i"] = 5; ["j"] = 2; ["k"] = 57; ["TYPE"] = 4; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 5; ["MIN_LVL"] = 19; ["NAME"] = "Истребление лесных троллей"; ["LORE"] = "Давным-давно речные хоббиты Туманного убежища впервые столкнулись с лесными демонами Лихолесья, и рассказы об этих ужасных существах стали легендами. Эльфы называют их лесными троллями, и говорят, что с их шишковатых конечностей капает смертельный яд - настолько страшный, что он может сгубить лес изнутри."; };
[1879468657] = {["ID"] = 1879468657; ["i"] = 5; ["j"] = 2; ["k"] = 56; ["TYPE"] = 4; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 10; ["MIN_LVL"] = 25; ["NAME"] = "Истребление лесных троллей II"; ["LORE"] = "Много рассказов о лесных демонах Севера, которые, как гнойная болезнь, распространились по старинному Зеленолесью. Ходят слухи, что другие, похожие на них существа, появились в землях далеко за пределами Лихолесья и истоков Долгой реки, и многие из речных хоббитов Туманного убежища теперь верят, что сама природа испорчена чьей-то невидимой рукой."; };
[1879468717] = {["ID"] = 1879468717; ["i"] = 5; ["j"] = 2; ["k"] = 58; ["TYPE"] = 4; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 15; ["MIN_LVL"] = 30; ["NAME"] = "Укрощение орков и гоблинов III"; ["LORE"] = "Хотя орки не любят солнце почти так же сильно, как их меньшие собратья, гоблины, они более терпимы к нему и могут выдержать его какое-то время, когда этого требует необходимость или плеть их хозяев. Несмотря на это, речные хоббиты Туманного убежища слишком хорошо знают, что орки и гоблины Севера часто бродят в туманах, застилающих истоки Долгой реки."; };
[1879468718] = {["ID"] = 1879468718; ["i"] = 5; ["j"] = 2; ["k"] = 59; ["TYPE"] = 4; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 10; ["MIN_LVL"] = 25; ["NAME"] = "Укрощение орков и гоблинов II"; ["LORE"] = "Орков и гоблинов нельзя назвать ни трусами, ни слабаками, но их часто рассеянная сила и решимость мало что дают против врага, которого они не могут найти, или против врага, в существовании которого они даже не уверены! Среди них ходят легенды и рассказы о речных хоббитах Туманного убежища, но на службе у врага нет времени говорить о таких пустяках."; };
[1879468719] = {["ID"] = 1879468719; ["i"] = 5; ["j"] = 2; ["k"] = 60; ["TYPE"] = 4; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 5; ["MIN_LVL"] = 19; ["NAME"] = "Укрощение орков и гоблинов"; ["LORE"] = "Выведенные врагом для войны, орки крупнее и выносливее своих сородичей гоблинов, но происхождение их одинаково, и для речных хоббитов Туманного убежища различий между ними почти нет. Воинственные и жестокие, орки и гоблины сохранили некоторый природный талант к искусной обработке дерева и металла, хотя применяют его только для создания оружия и разных боевых машин."; };
[1879468766] = {["ID"] = 1879468766; ["i"] = 5; ["j"] = 2; ["k"] = 61; ["TYPE"] = 7; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 5; ["MIN_LVL"] = 25; ["NAME"] = "Друг Забытых"; ["LORE"] = "Вы стали другом людей-эгланов, которые сторонятся общества, предпочитая скудную жизнь в Пустошах. Хотя они обитают в менее гостеприимных землях, чем истоки Долгой реки, их образ жизни и дружба с Радагастом Карим побудили вас считать их родственными душами речных хоббитов Туманного убежища."; ["TITLE"] = "речной бегун"; };
[1879468771] = {["ID"] = 1879468771; ["i"] = 5; ["j"] = 2; ["k"] = 62; ["TYPE"] = 6; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 10; ["MIN_LVL"] = 125; ["NAME"] = "Обратно и снова туда"; ["LORE"] = "Немногие из речных хоббитов побывали так далеко от дома, как вы, но даже после всех ваших приключений мало что может принести вам больший уют, чем возвращение в Туманное убежище."; ["TITLE"] = "речной наездник"; };
