[1879487903] = {["ID"] = 1879487903; ["i"] = 5; ["j"] = 4; ["k"] = 425; ["TYPE"] = 12; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Победить Зловещего Южанина"; ["LORE"] = "Мало кто из живущих слышал его речь, однако облик его был хорошо известен и внушал ужас. Он получил имя Зловещий Южанин, и в то время, в течение всей Второй эпохи, люди прятались при одном его приближении, во время Третьей легенды о его злобе распространились еще шире. Впоследствии именно за ним в Дол Гулдур тайно следовала Лаэрет Несущая Мор, где она нашла Саурона и за определенную плату помогла ему восстановиться. Вознаградил или наказал за совершенную оплошность Темный Властелин своего назгула? Все это случилось потом. Во время Второй эпохи о Зловещем Южанине было известно только, что он терпелив, предан и безмолвен."; ["TITLE"] = "Dawn of the South"; };
[1879487969] = {["ID"] = 1879487969; ["i"] = 5; ["j"] = 4; ["k"] = 433; ["TYPE"] = 12; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Победить Короля-Призрака"; ["LORE"] = "Величайший и самый грозный из Девятерых, Король-Призрак редко шествовал по полю битвы, покидая крепости Мордора только по самому неотложному приказу Саурона. Годами позже предводитель назгулов положит начало возникновению Ангмара, используя его земли для достижения замысла Темного Властелина - уничтожения северного королевства Арнор, но в конце Второй Эпохи эти события были сокрыты туманом времени. Во время осады Барад-Дура Король-Призрак занимался выявлением наиболее уязвимых мест в обороне армий, которые противостояли его хозяину, и добычей самого ценного из трофеев - информации."; ["TITLE"] = "the Last Hope of the North"; };
[1879487972] = {["ID"] = 1879487972; ["i"] = 5; ["j"] = 4; ["k"] = 432; ["TYPE"] = 12; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Победить Проклятого Всадника"; ["LORE"] = "Он проносился по полю боя, повергая воинов, осмелившихся выступить против него, и таковых становилось все меньше по мере продолжения осады. Его знали как Проклятого Всадника, и при одних только звуках его приближения храбрецы становились трусами. В последующие годы он командовал армиями Дол Гулдура, но во время Второй эпохи предпочитал сражаться в одиночку верхом на своем черном коне."; ["TITLE"] = "Curse-breaker"; };
[1879487973] = {["ID"] = 1879487973; ["i"] = 5; ["j"] = 4; ["k"] = 431; ["TYPE"] = 12; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Победить Проклятие Кханда"; ["LORE"] = "Он был Проклятьем Кханда, и с благословения Саурона шествовал по непокоренным землям и захватывал их во имя Темного Властелина. Кольцо, дарованное ему, звалось Адаш, и он нажил много врагов с его помощью, многих гордых воинов низверг. Он находил великую радость в разжигании войн и не упускал ради этого ни единой возможности, однако с властью, дарованной ему Сауроном, Проклятье Кханда стал еще более смертоносным, безжалостным и неумолимым."; ["TITLE"] = "the Joy of Khand"; };
[1879487974] = {["ID"] = 1879487974; ["i"] = 5; ["j"] = 4; ["k"] = 430; ["TYPE"] = 12; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Победить Верховного чародея Харада"; ["LORE"] = "Они прозвали его Верховным чародеем Харада, но для большинства из тех, кто сражался против Саурона, это было всего лишь имя. Он редко покидал подземелья крепостей Мордора, так как находил наслаждение в проведении темных ритуалов и в постижении тайн темного колдовства, что-либо другое мало занимало его мысли. Однако когда ему доводилось оставлять подземелья по приказу Темного Властелина, люди и эльфы стремились держаться от него как можно дальше, дабы избежать боли и страданий. Он получил кольцо Мэбат, Пожирающее радость, и куда бы он ни шел, везде смолкал смех и воцарялось горе."; ["TITLE"] = "the Sorcerer's Downfall"; };
[1879487975] = {["ID"] = 1879487975; ["i"] = 5; ["j"] = 4; ["k"] = 429; ["TYPE"] = 12; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Победить Погибель Руна"; ["LORE"] = "Когда-то он был великим королем из далеких земем на востоке, привыкшим править и не желавшим преклонять колена ни перед кем другим. Но затем явился преподносящий дары и сулящий власть, и, поддавшись соблазну, великий король изменился. С тех пор он не правил своими землями с милосердием и покинул собственное королевство. Он принес погибель в Рун и другие земли, и под этим именем стал известен как Погибель Руна."; ["TITLE"] = "Saviour of Rhûn"; };
[1879487976] = {["ID"] = 1879487976; ["i"] = 5; ["j"] = 4; ["k"] = 428; ["TYPE"] = 12; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Победить Черного Клинка Лебеннина"; ["LORE"] = "В последнее время Черного Клинка Лебеннина часто видели крадущимся среди холмов и лесов Западного Гондора, вселяющим ужас в сердца людей как своим мертвенным обликом, так и зловещим мечом. Что касается тех немногих, кому не удалось бежать - его речи словно мед лились в их безвольные уши и вели к чудовищным злодеяниям. Это, скорее всего, и было его самым грозным и эффективным оружием."; ["TITLE"] = "the Blade-breaker"; };
[1879487977] = {["ID"] = 1879487977; ["i"] = 5; ["j"] = 4; ["k"] = 427; ["TYPE"] = 12; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Победить Мрак Нурна"; ["LORE"] = "Никто не может сказать, какой корабль принес его сюда, в Средиземье, до затопления Нуменора, но как только он принял дар Саурона, его уже нельзя было причислить к числу людей из тех земель. Он поселился в Таурбанде, крепости в южном Мордоре, неподалеку от внутреннего моря. Именно из той крепости и распространилась ужасная молва о нем, давшая ему новое имя взамен того, в котором он больше не нуждался. Его прозвали Мраком Нурна, несмотря на то, что он покинул те места и скитался повсюду по приказу Саурона."; ["TITLE"] = "a Light in the Gloom"; };
[1879487978] = {["ID"] = 1879487978; ["i"] = 5; ["j"] = 4; ["k"] = 426; ["TYPE"] = 12; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Победить Отрёкшегося Разорителя"; ["LORE"] = "Он пришел с далекого юга, принося с собой ужас и огонь на каждый берег, что замечал в свою подзорную трубу. Его царствование было кровавым - он черпал кровь у всех, кто имел несчастье жить на побережье и вдыхать запахи моря. Не по этой ли причине Саурон дал ему кольцо Канто, Приносящее страдания? Отрёкшегося Разорителя, наделенного властью кольца, невозможно было остановить, и его хохот, подхваченный ветрами, разносился вглубь земель; он был одним из самых быстрых слуг Саурона и самым жестоким."; ["TITLE"] = "Forsaken No More"; };
[1879489234] = {["ID"] = 1879489234; ["i"] = 5; ["j"] = 4; ["k"] = 408; ["TYPE"] = 7; ["TIER"] = 2; ["NAME"] = "Bean-spiller"; ["LORE"] = "You were tripped up by a sneaky hobbit in the Hard Tack of Thorin's Hall event several times."; ["TITLE"] = "Bean-spiller"; };
[1879489238] = {["ID"] = 1879489238; ["i"] = 5; ["j"] = 4; ["k"] = 407; ["TYPE"] = 7; ["TIER"] = 1; ["NAME"] = "Clod"; ["LORE"] = "Many brazen hobbits have been well fed by your clumsy ineptitude. For this ignoble honour, you shall be known as a clod forever more."; ["TITLE"] = "the Clod"; };
