[1879495455] = {["ID"] = 1879495455; ["i"] = 2; ["j"] = 17; ["k"] = 15; ["TYPE"] = 4; ["VXP"] = 1000; ["TIER"] = 1; ["MIN_LVL"] = 150; ["NAME"] = "Vanquisher of Tûl Zakana, the Well of Forgetting"; ["LORE"] = "Deep in the war-torn lands of Imhûlar, locals warn you of an Ordâkhai encampment, a trading post of sorts. It is known as Tûl Zakana, the Well of Forgetting, whose waters will make you forget your troubles, and, if you drink enough, even who you are. But unless you are trading for this water, it's best to stay well clear of the Well, for many have vanished near it, never to be seen again. You are now tasked by the families of the vanished with investigating the Well and its secrets."; ["TITLE"] = "the Absent-minded"; };
